with won as (select distinct f.n, t.discount from public.market_contractor_facts f join public.market_tender_facts t on t.adam = f.n where f.ckey in ('094496049','997802310','094428065','094316657','801079752','094283081','094399329','800647473','094212174','094213379','997759560','094437210') and t.discount is not null)
select count(*) as tenders_in_median, round((percentile_cont(0.5) within group (order by discount) * 100)::numeric, 2) as median_pct, round((avg(discount) * 100)::numeric, 2) as mean_pct, round((min(discount) * 100)::numeric, 2) as min_pct, round((max(discount) * 100)::numeric, 2) as max_pct from won;
with won as (select distinct f.n, t.discount from public.market_contractor_facts f join public.market_tender_facts t on t.adam = f.n where f.ckey in ('094496049','997802310','094428065','094316657','801079752','094283081','094399329','800647473','094212174','094213379','997759560','094437210') and t.discount is not null)
select case when discount <= 0.0005 then '0. έως 0,05%' when discount < 0.01 then '1. 0,05-1%' when discount < 0.05 then '2. 1-5%' when discount < 0.10 then '3. 5-10%' when discount < 0.20 then '4. 10-20%' when discount < 0.40 then '5. 20-40%' else '6. πάνω από 40%' end as bucket, count(*) as tenders from won group by 1 order by 1;
with won as (select distinct f.n, t.discount from public.market_contractor_facts f join public.market_tender_facts t on t.adam = f.n where f.ckey in ('094496049','997802310','094428065','094316657','801079752','094283081','094399329','800647473','094212174','094213379','997759560','094437210') and t.discount is not null),
ranked as (select n, discount, row_number() over (order by discount) as rn, count(*) over () as total from won)
select r.rn, r.total, r.n as tender, round((r.discount * 100)::numeric, 2) as discount_pct, round(t.budget::numeric) as budget, round((t.budget * (1 - r.discount))::numeric) as amount, left(t.authority_name, 40) as authority
from ranked r join public.market_tender_facts t on t.adam = r.n where r.rn between (r.total + 1) / 2 - 2 and (r.total + 1) / 2 + 2 order by r.rn;
